#include <stdio.h>
int main() {
    int sum = 0;
    for (int j = 0; j < 36; j++) {
        if (j % 5 == 0) continue;
        if (j > 15) break;
        sum += j;
    }
    printf("sum: %d\n", sum);

    int k = 0;
    while (k < 36) {
        k += 3;
    }
    printf("while_k: %d\n", k);

    int m = 0;
    do {
        m += 2;
    } while (m < 36);
    printf("dowhile_m: %d\n", m);
    return 0;
}
